func TestBackupRefusesASymlinkedDestinationInsideTheStore(t *testing.T) {
	target := survivorStore(t)
	alias := filepath.Join(t.TempDir(), "alias")
	if err := os.Symlink(target.StoreDir, alias); err != nil {
		t.Fatal(err)
	}
