func TestSiblingLeafCannotInterceptAnotherChild(t *testing.T) {
	ctx, cancel := context.WithTimeout(t.Context(), 60*time.Second)
	defer cancel()
	gru, gruRuntime, sfoRuntime, addr, leafTLS := startHubWithChild(ctx, t)

	sfoQuery, err := sfoRuntime.Conn().Subscribe(protocol.Regional("sfo", "query", "status"), func(msg *nats.Msg) {
		_ = msg.Respond([]byte("sfo-ok"))
	})
	if err != nil {
		t.Fatal(err)
	}
	defer sfoQuery.Unsubscribe()
	if err := sfoRuntime.Conn().Flush(); err != nil {
		t.Fatal(err)
	}
	if reply := requestUntil(ctx, t, gruRuntime.Conn(), protocol.Regional("sfo", "query", "status")); string(reply.Data) != "sfo-ok" {
		t.Fatalf("baseline query = %q", reply.Data)
	}
	assertObservabilityCrossesNarrowly(ctx, t, gruRuntime, sfoRuntime)

	sibling := dialRawLeaf(ctx, t, addr, leafTLS, gru.childLeafCredentials(t, "fra-leaf.creds", "fra"))
	defer sibling.close()
	for _, wildcard := range []string{"ts.orch.v1.sfo.>", "ts.orch.v1.*.query.>", "ts.interregion.v1.>", ">"} {
		sibling.subscribe(t, wildcard)
	}
	time.Sleep(300 * time.Millisecond)
	for range 5 {
		reply := requestUntil(ctx, t, gruRuntime.Conn(), protocol.Regional("sfo", "query", "status"))
		if string(reply.Data) != "sfo-ok" {
			t.Fatalf("query to SFO answered by someone else: %q", reply.Data)
		}
	}
	// SFO's mirror feed and its observability requests are SFO's alone too.
	for range 5 {
		if err := gruRuntime.Conn().Publish(protocol.InterRegionGlobalDeliverSubject("sfo"), []byte("feed")); err != nil {
			t.Fatal(err)
		}
		for _, leaf := range protocol.InterRegionObservabilityLeaves() {
			requestCtx, requestCancel := context.WithTimeout(ctx, 200*time.Millisecond)
			_, _ = gruRuntime.Conn().RequestWithContext(requestCtx, protocol.InterRegionObservabilitySubject("sfo", leaf),
				[]byte(`{"version":1}`))
			requestCancel()
		}
	}
	if err := gruRuntime.Conn().Flush(); err != nil {
		t.Fatal(err)
	}
	if subject, got := sibling.awaitMessage(t, "ts.", 500*time.Millisecond); got {
		t.Fatalf("FRA's leaf intercepted %q addressed to SFO", subject)
	}

	// FRA cannot speak for SFO either: its health is refused and the link closes.
	impostor := dialRawLeaf(ctx, t, addr, leafTLS, gru.childLeafCredentials(t, "fra-impostor.creds", "fra"))
	impostor.publish(t, protocol.RegionHealthSubject("sfo"), "", []byte("forged"))
	if reason := impostor.awaitClose(t); !strings.Contains(reason, "Permissions Violation for Publish") {
		t.Fatalf("FRA published SFO's health; link closed with %q", reason)
	}
	resetter := dialRawLeaf(ctx, t, addr, leafTLS, gru.childLeafCredentials(t, "fra-reset.creds", "fra"))
	resetter.publish(t, protocol.JSConsumerResetSubject(protocol.JSDomainAPIPrefix("gru"), protocol.GlobalControlStream,
		protocol.GlobalMirrorConsumer("sfo")), "", []byte(`{"seq":99}`))
	if reason := resetter.awaitClose(t); !strings.Contains(reason, "Permissions Violation for Publish") {
		t.Fatalf("FRA reset SFO's mirror consumer; link closed with %q", reason)
	}
	// A user signed by the interregion account identity key rather than a
	// child's scoped key gets the deny-all defaults, even for FRA's subjects.
	identity := dialRawLeaf(ctx, t, addr, leafTLS, gru.leafCredentials(t, "identity.creds"))
	identity.publish(t, protocol.RegionHealthSubject("fra"), "", []byte("unscoped"))
	if reason := identity.awaitClose(t); !strings.Contains(reason, "Permissions Violation for Publish") {
		t.Fatalf("unscoped leaf user published; link closed with %q", reason)
	}
	// Its own region's subjects still cross.
	own := dialRawLeaf(ctx, t, addr, leafTLS, gru.childLeafCredentials(t, "fra-own.creds", "fra"))
	defer own.close()
	health := make(chan *nats.Msg, 4)
	healthSub, err := gruRuntime.Conn().ChanSubscribe(protocol.RegionHealthSubject("fra"), health)
	if err != nil {
		t.Fatal(err)
	}
	defer healthSub.Unsubscribe()
	if err := gruRuntime.Conn().Flush(); err != nil {
		t.Fatal(err)
	}
	for {
		own.publish(t, protocol.RegionHealthSubject("fra"), "", []byte("fra-health"))
		select {
		case msg := <-health:
			if string(msg.Data) == "fra-health" {
				return
			}
		case <-time.After(100 * time.Millisecond):
		case <-ctx.Done():
			t.Fatal("FRA's own health did not cross")
		}
	}
}

func TestChildLeafPermissionsAreScopedToTheSubtree(t *testing.T) {
	t.Parallel()

	// IAD dials SFO; SFO and FRA dial GRU.
	topology := HubAndSpoke("gru", []string{"fra", "iad", "sfo"}).WithSpokeParent("iad", "sfo")
	subtrees := topology.Subtrees("gru")
	if !slices.Equal(subtrees["sfo"], []string{"iad", "sfo"}) || !slices.Equal(subtrees["fra"], []string{"fra"}) || len(subtrees) != 2 {
		t.Fatalf("subtrees = %v", subtrees)
	}
	if spoke := topology.Subtrees("sfo"); len(spoke) != 1 || !slices.Equal(spoke["iad"], []string{"iad"}) {
		t.Fatalf("sfo subtrees = %v", spoke)
	}
	contract := InterRegionContract{Cell: "gru", Peers: topology.Peers("gru"), GlobalHome: "gru", Subtrees: subtrees}
	sfo := contract.ChildLeafPermissions("sfo")
	reset := func(region string) string {
		return protocol.JSConsumerResetSubject(protocol.JSDomainAPIPrefix("gru"), protocol.GlobalControlStream,
			protocol.GlobalMirrorConsumer(region))
	}
	for _, own := range []string{"sfo", "iad"} {
		if !slices.Contains(sfo.Pub.Allow, protocol.RegionHealthSubject(own)) || !slices.Contains(sfo.Pub.Allow, reset(own)) ||
			!slices.Contains(sfo.Sub.Allow, protocol.Regional(own, "query", ">")) ||
			!slices.Contains(sfo.Sub.Allow, protocol.InterRegionGlobalDeliverSubject(own)) {
			t.Errorf("SFO's leaf lacks its subtree region %s", own)
		}
	}
	for _, foreign := range []string{"fra", "gru"} {
		if slices.Contains(sfo.Pub.Allow, protocol.RegionHealthSubject(foreign)) || slices.Contains(sfo.Pub.Allow, reset(foreign)) ||
			slices.Contains(sfo.Sub.Allow, protocol.Regional(foreign, "query", ">")) ||
			slices.Contains(sfo.Sub.Allow, protocol.InterRegionGlobalDeliverSubject(foreign)) {
			t.Errorf("SFO's leaf may act for %s", foreign)
		}
	}
	if unknown := contract.ChildLeafPermissions("lhr"); !denyAll(unknown) {
		t.Fatalf("unknown child permissions = %+v", unknown)
	}

	keys := newTestRegionKeys(t)
	system, cell, interregion := keys.claims(contract, 2)
	if err := contract.verify(system, cell, interregion, 2); err != nil {
		t.Fatal(err)
	}
	if !denyAll(interregion.DefaultPermissions) {
		t.Fatal("interregion defaults are not deny-all")
	}
	scopeOf := func(claim *jwt.AccountClaims, child string) *jwt.UserScope {
		for _, scope := range claim.SigningKeys {
			if user, ok := scope.(*jwt.UserScope); ok && user.Role == child {
				return user
			}
		}
		t.Fatalf("no scope for %s", child)
		return nil
	}
	mutations := map[string]func(*jwt.AccountClaims){
		"unscoped signing key": func(claim *jwt.AccountClaims) {
			extra, _ := nkeys.CreateAccount()
			public, _ := extra.PublicKey()
			claim.SigningKeys.Add(public)
		},
		"missing child scope": func(claim *jwt.AccountClaims) {
			delete(claim.SigningKeys, scopeOf(claim, "fra").Key)
		},
		"widened template": func(claim *jwt.AccountClaims) {
			scopeOf(claim, "fra").Template.Pub.Allow.Add(protocol.RegionHealthSubject("sfo"))
		},
		"sibling template": func(claim *jwt.AccountClaims) {
			scopeOf(claim, "fra").Template.Permissions = contract.ChildLeafPermissions("sfo")
		},
		"client connections": func(claim *jwt.AccountClaims) {
			scopeOf(claim, "fra").Template.AllowedConnectionTypes = jwt.StringList{jwt.ConnectionTypeStandard}
		},
		"bearer users":   func(claim *jwt.AccountClaims) { scopeOf(claim, "fra").Template.BearerToken = true },
		"unknown role":   func(claim *jwt.AccountClaims) { scopeOf(claim, "fra").Role = "lhr" },
		"duplicate role": func(claim *jwt.AccountClaims) { scopeOf(claim, "fra").Role = "sfo" },
		"permissive defaults": func(claim *jwt.AccountClaims) {
			claim.DefaultPermissions = contract.LeafPermissions()
		},
	}
	for name, mutate := range mutations {
		system, cell, interregion := keys.claims(contract, 2)
		mutate(interregion)
		if err := contract.verify(system, cell, interregion, 2); err == nil {
			t.Errorf("%s: widened interregion account verified", name)
		}
	}
}

func TestIssueLinkUserCarriesOnlyTheLinkClaim(t *testing.T) {
	signer, err := nkeys.CreateAccount()
	if err != nil {
		t.Fatal(err)
	}
	signerID, _ := signer.PublicKey()
	home, _ := nkeys.CreateAccount()
	homeID, _ := home.PublicKey()
	now := time.Now()
	creds, err := IssueLinkUser(signer, homeID, "sfo", now, now.Add(time.Hour))
	if err != nil {
		t.Fatal(err)
	}
	raw, err := nkeys.ParseDecoratedJWT(creds)
	if err != nil {
		t.Fatal(err)
	}
	claim, err := jwt.DecodeUserClaims(raw)
	if err != nil {
		t.Fatal(err)
	}
	if claim.IssuerAccount != homeID || claim.Issuer != signerID || !slices.Equal(claim.Tags, jwt.TagList{"cell:sfo"}) ||
		!claim.HasEmptyPermissions() {
		t.Fatalf("link user claim = %+v", claim)
	}
	if err := validateLinkCredentials(writeTempFile(t, creds), "sfo"); err != nil {
		t.Fatalf("issued link user rejected: %v", err)
	}
	if _, err := IssueLinkUser(signer, homeID, "SFO", now, now.Add(time.Hour)); err == nil {
		t.Fatal("noncanonical cell accepted")
	}
	if _, err := IssueLinkUser(signer, signerID+"x", "sfo", now, now.Add(time.Hour)); err == nil {
		t.Fatal("invalid home account accepted")
	}
}

func TestLinkScopeIsOneTemplateForEveryRegion(t *testing.T) {
	signer, err := nkeys.CreateAccount()
	if err != nil {
		t.Fatal(err)
	}
	signerID, _ := signer.PublicKey()
	scope := LinkScope(signerID)
	if scope.Key != signerID || scope.Role != "link" {
		t.Fatalf("link scope key/role = %q/%q", scope.Key, scope.Role)
	}
	for _, subject := range []string{"ts.orch.v1.*.query.>", "ts.orch.v1.*.obs.region", "ts.orch.v1.*.obs.decisions",
		"ts.orch.v1.{{tag(cell)}}.region.>",
		"$JS.gru.API.CONSUMER.RESET.TS_GLOBAL_CONTROL.global-mirror-{{tag(cell)}}",
		"$JS.FC.TS_GLOBAL_CONTROL.global-mirror-{{tag(cell)}}.*"} {
		if !slices.Contains(scope.Template.Pub.Allow, subject) {
			t.Fatalf("link may not send %q", subject)
		}
	}
	for _, subject := range []string{"ts.orch.v1.{{tag(cell)}}.query.>", "ts.orch.v1.{{tag(cell)}}.obs.region",
		"ts.orch.v1.{{tag(cell)}}.obs.decisions", "ts.orch.v1.*.region.>", "ts.interregion.v1.{{tag(cell)}}.global",
		"ts.orch.v1.{{tag(cell)}}.inbox.>", "_INBOX.>", "$JSC.R.>"} {
		if !slices.Contains(scope.Template.Sub.Allow, subject) {
			t.Fatalf("link may not receive %q", subject)
		}
	}
	for _, subject := range scope.Template.Pub.Allow {
		if strings.Contains(subject, "host.register") || strings.HasPrefix(subject, "$KV") || strings.HasPrefix(subject, "ts.control") {
			t.Fatalf("link may send regional-only subject %q", subject)
		}
	}
	if scope.Template.Resp == nil || scope.Template.Resp.MaxMsgs != 1 || scope.Template.Resp.Expires != time.Minute {
		t.Fatalf("link responses = %+v", scope.Template.Resp)
	}
	if !slices.Equal(scope.Template.AllowedConnectionTypes, jwt.StringList{jwt.ConnectionTypeLeafnode}) {
		t.Fatalf("link connection types = %v", scope.Template.AllowedConnectionTypes)
	}
}

func TestLinkStarRelaysEveryRegionThroughTheHome(t *testing.T) {
	ctx, cancel := context.WithTimeout(t.Context(), 90*time.Second)
	defer cancel()
	root := t.TempDir()
	signer, err := nkeys.CreateAccount()
	if err != nil {
		t.Fatal(err)
	}
	signerID, _ := signer.PublicKey()
	names := []string{"gru", "sfo", "fra"}
	regions := map[string]*testRegion{}
	for _, name := range names {
		regions[name] = newLinkRegion(t, filepath.Join(root, name), name, signerID)
	}
	tlsFiles := testBridgeTLS(t, filepath.Join(root, "link-tls"))
	port := freeClientPort(t)
	useLinkListener(t, port)
	regions["gru"].cfg.Embedded.Link = &Link{TLS: tlsFiles}
	spokeCreds := map[string]string{}
	for _, name := range []string{"sfo", "fra"} {
		spokeCreds[name] = linkUserCredentials(t, root, name+"-link.creds", signer, regions["gru"].cellID, name)
		regions[name].cfg.Embedded.Link = &Link{CredentialsFile: spokeCreds[name], TLS: tlsFiles}
	}
	runtimes := map[string]*Runtime{}
	for _, name := range names {
		regions[name].cfg.CredentialsFile = linkControllerCredentials(t, root, name+"-controller.creds", regions[name])
		runtime, err := Start(ctx, regions[name].cfg)
		if err != nil {
			t.Fatalf("start %s: %v", name, err)
		}
		t.Cleanup(func() { _ = runtime.Close() })
		runtimes[name] = runtime
	}
	waitLeafCount(ctx, t, runtimes["gru"], 2)

	// a: observability requests in all six directions.
	for _, name := range names {
		_, err := runtimes[name].Conn().Subscribe(protocol.InterRegionObservabilitySubject(name, protocol.ObservabilityRegionLeaf),
			func(msg *nats.Msg) { _ = msg.Respond([]byte(name + "/region")) })
		if err != nil {
			t.Fatal(err)
		}
	}
	if err := runtimes["gru"].Conn().Flush(); err != nil {
		t.Fatal(err)
	}
	for _, from := range names {
		for _, to := range names {
			if from == to {
				continue
			}
			subject := protocol.InterRegionObservabilitySubject(to, protocol.ObservabilityRegionLeaf)
			if reply := requestUntil(ctx, t, runtimes[from].Conn(), subject); string(reply.Data) != to+"/region" {
				t.Fatalf("%s -> %s region reply = %q", from, to, reply.Data)
			}
		}
	}

	// b: a query from SFO is answered by FRA alone.
	if _, err := runtimes["fra"].Conn().Subscribe(protocol.SubjectRoot+".fra.query.>",
		func(msg *nats.Msg) { _ = msg.Respond([]byte("fra-query")) }); err != nil {
		t.Fatal(err)
	}
	if err := runtimes["fra"].Conn().Flush(); err != nil {
		t.Fatal(err)
	}
	if reply := requestUntil(ctx, t, runtimes["sfo"].Conn(), protocol.Regional("fra", "query", "terrabase-wan", "x")); string(reply.Data) != "fra-query" {
		t.Fatalf("query from sfo answered by %q", reply.Data)
	}

	// c: every region receives every region's health.
	awaitEveryBroadcast(ctx, t, runtimes, names, protocol.RegionHealthSubject, protocol.SubjectRoot+".*.region.health")
	awaitEveryBroadcast(ctx, t, runtimes, names, protocol.RegionRollupSubject, protocol.RegionRollupGrant)

	// d: a raw leaf with SFO's link user cannot receive FRA's requests and
	// cannot publish outside its own region.
	addr := net.JoinHostPort("127.0.0.1", strconv.Itoa(port))
	spoke := dialRawLeaf(ctx, t, addr, tlsFiles, spokeCreds["sfo"])
	defer spoke.close()
	spoke.subscribe(t, protocol.SubjectRoot+".fra.>")
	time.Sleep(200 * time.Millisecond)
	// Requests only: SFO's leaf does receive FRA's health, which it may.
	for range 5 {
		requestCtx, cancel := context.WithTimeout(ctx, 200*time.Millisecond)
		_, _ = runtimes["gru"].Conn().RequestWithContext(requestCtx, protocol.Regional("fra", "query", "terrabase-wan", "raw"), []byte("q"))
		cancel()
	}
	if subject, got := spoke.awaitMessage(t, protocol.SubjectRoot+".fra.query.", 300*time.Millisecond); got {
		t.Fatalf("SFO's leaf received FRA's request %q", subject)
	}
	for _, forbidden := range []string{protocol.RegionHealthSubject("fra"), protocol.HostRegisterSubject(LinkHome), "$KV.TS_X.k"} {
		intruder := dialRawLeaf(ctx, t, addr, tlsFiles, spokeCreds["sfo"])
		intruder.publish(t, forbidden, "", []byte("forged"))
		if reason := intruder.awaitClose(t); !strings.Contains(reason, "Permissions Violation for Publish") {
			t.Fatalf("SFO's leaf published %q; link closed with %q", forbidden, reason)
		}
	}

	// e: a command published in GRU never reaches SFO. The admin user is
	// test-only: a controller may not publish another region's commands.
	admin := linkAdminConnection(t, root, runtimes["gru"], regions["gru"])
	commands := make(chan *nats.Msg, 8)
	commandSub, err := runtimes["sfo"].Conn().ChanSubscribe(protocol.HostRegisterSubject("sfo"), commands)
	if err != nil {
		t.Fatal(err)
	}
	defer commandSub.Unsubscribe()
	if err := runtimes["sfo"].Conn().Flush(); err != nil {
		t.Fatal(err)
	}
	for range 5 {
		if err := admin.Publish(protocol.HostRegisterSubject("sfo"), []byte("command")); err != nil {
			t.Fatal(err)
		}
	}
	if err := admin.Flush(); err != nil {
		t.Fatal(err)
	}
	time.Sleep(500 * time.Millisecond)
	if len(commands) != 0 {
		t.Fatalf("a command published in GRU reached SFO: %d messages", len(commands))
	}
}

func TestLinkValidationRefusesMisconfiguredRegions(t *testing.T) {
	signer, err := nkeys.CreateAccount()
	if err != nil {
		t.Fatal(err)
	}
	signerID, _ := signer.PublicKey()
	root := t.TempDir()
	gru := newLinkRegion(t, filepath.Join(root, "gru"), "gru", signerID)
	tlsFiles := testBridgeTLS(t, filepath.Join(root, "tls"))
	gru.cfg.CredentialsFile = "controller.creds"
	gru.cfg.Embedded.Link = &Link{TLS: tlsFiles}
	if err := gru.cfg.validate(); err != nil {
		t.Fatalf("home link rejected: %v", err)
	}
	both := gru.cfg
	both.Embedded = &Embedded{}
	*both.Embedded = *gru.cfg.Embedded
	both.Embedded.InterRegion = &InterRegion{AccountJWTFile: "x"}
	if err := both.validate(); err == nil {
		t.Fatal("interregion and link accepted together")
	}
	withCreds := gru.cfg
	withCreds.Embedded = &Embedded{}
	*withCreds.Embedded = *gru.cfg.Embedded
	withCreds.Embedded.Link = &Link{CredentialsFile: "x", TLS: tlsFiles}
	if err := withCreds.validate(); err == nil {
		t.Fatal("home with link credentials accepted")
	}
	spoke := newLinkRegion(t, filepath.Join(root, "sfo"), "sfo", signerID)
	spoke.cfg.CredentialsFile = "controller.creds"
	spoke.cfg.Embedded.Link = &Link{TLS: tlsFiles}
	if err := spoke.cfg.validate(); err == nil {
		t.Fatal("spoke without link credentials accepted")
	}
	fraCreds := linkUserCredentials(t, root, "fra.creds", signer, gru.cellID, "fra")
	if err := validateLinkCredentials(fraCreds, "sfo"); err == nil {
		t.Fatal("link user for another cell accepted")
	}
	sfoCreds := linkUserCredentials(t, root, "sfo.creds", signer, gru.cellID, "sfo")
	if err := validateLinkCredentials(sfoCreds, "fra"); err == nil {
		t.Fatal("link user tagged for sfo accepted by fra")
	}
	if err := VerifyLinkScope(jwt.NewAccountClaims(gru.cellID)); err == nil {
		t.Fatal("home cell account without the link signer accepted")
	}
	mutated := jwt.NewAccountClaims(gru.cellID)
	ApplyLink(mutated, signerID)
	scope := mutated.SigningKeys[signerID].(*jwt.UserScope)
	scope.Template.Sub.Allow = append(scope.Template.Sub.Allow, "ts.control.>")
	if err := VerifyLinkScope(mutated); err == nil {
		t.Fatal("link template with regional-only subjects accepted")
	}
}

func TestClientErrorsLogAtTheirSeverity(t *testing.T) {
	output := captureDefault(t)
	ErrorHandler(nil, nil, nats.ErrPermissionViolation)
	ErrorHandler(nil, nil, nats.ErrAuthorization)
	ErrorHandler(nil, nil, errors.New("slow consumer"))
	want := []string{"ERROR", "ERROR", "WARN"}
	lines := bytes.Split(bytes.TrimSpace(output.Bytes()), []byte("\n"))
	if len(lines) != len(want) {
		t.Fatalf("wrote %d records, want %d: %s", len(lines), len(want), output)
	}
	for i, line := range lines {
		var record map[string]any
		if err := json.Unmarshal(line, &record); err != nil {
			t.Fatal(err)
		}
		if record["level"] != want[i] || record["component"] != "nats-client" {
			t.Fatalf("record %d = %v, want level %s", i, record, want[i])
		}
	}
}

func TestNATSServerOutputMapsToLevels(t *testing.T) {
	output := captureDefault(t)
	var logger natsLogger
	logger.Noticef("ready %d", 1)
	logger.Warnf("slow consumer %s", "x")
	logger.Warnf("Metalayer blocking snapshot for peer %s", "p1")
	logger.Errorf("store failed")
	logger.Fatalf("fatal")
	logger.Debugf("debug")
	logger.Tracef("trace")
	want := []struct{ level, message string }{
		{"INFO", "ready 1"}, {"WARN", "slow consumer x"},
		{"INFO", "Metalayer blocking snapshot for peer p1"}, {"ERROR", "store failed"},
		{"ERROR", "fatal"}, {"DEBUG", "debug"}, {"DEBUG", "trace"},
	}
	lines := bytes.Split(bytes.TrimSpace(output.Bytes()), []byte("\n"))
	if len(lines) != len(want) {
		t.Fatalf("wrote %d records, want %d: %s", len(lines), len(want), output)
	}
	for i, line := range lines {
		var record map[string]any
		if err := json.Unmarshal(line, &record); err != nil {
			t.Fatal(err)
		}
		if record["level"] != want[i].level || record["msg"] != want[i].message || record["component"] != "nats" {
			t.Fatalf("record %d = %v, want %s %q", i, record, want[i].level, want[i].message)
		}
	}
}

func TestStreamViewReportsTheConfiguredReplicationFactor(t *testing.T) {
	two := []*server.PeerInfo{{Name: "b"}, {Name: "c"}}
	three := []*server.PeerInfo{{Name: "a"}, {Name: "b"}, {Name: "c"}}
	for _, test := range []struct {
		name   string
		stream server.StreamDetail
		want   int
	}{
		{"configured leaderless", server.StreamDetail{Config: &server.StreamConfig{Replicas: 3},
			Cluster: &server.ClusterInfo{Replicas: three}}, 3},
		{"configured led", server.StreamDetail{Config: &server.StreamConfig{Replicas: 3},
			Cluster: &server.ClusterInfo{Leader: "a", Replicas: two}}, 3},
		{"fallback led", server.StreamDetail{Cluster: &server.ClusterInfo{Leader: "a", Replicas: two}}, 3},
		{"fallback leaderless", server.StreamDetail{Cluster: &server.ClusterInfo{Replicas: three}}, 3},
