func TestReloadingTLSRollsOverTheCA(t *testing.T) {
	old, next := newTestCA(t, "cell CA"), newTestCA(t, "cell CA")
	files := testTLSFiles(t)
	certPEM, keyPEM, _ := old.leaf(t, "gru-1-ctl-1", "127.0.0.1", time.Now().Add(time.Hour))
