	last := ledger{Generation: 20, Epoch: 3, Transaction: "2S68NEPB3AF7KVEFYXRZVNNGRJ", Action: "confirm", ActionID: network.CommandID("2S68NEPB3AF7KVEFYXRZVNNGRJ", "confirm")}
