	interrupted := ledger{Generation: 21, Epoch: 4, Transaction: "7WVH811H6PKN5FZS9M96YYWYMF", Action: "install", ActionID: network.CommandID("2S68NEPB3AF7KVEFYXRZVNNGRJ", "confirm")}
