			suffix, err := filepath.Rel(replaced, directory)
			if err != nil {
				t.Fatal(err)
			}
			outsideSpool := filepath.Join(outside, suffix)
			if err := os.MkdirAll(outsideSpool, 0700); err != nil {
				t.Fatal(err)
			}
