			outside := t.TempDir()
			if kind == "symlink" {
				err = os.Symlink(outside, directory)
			} else {
				err = os.Mkdir(directory, 0700)
				outside = directory
			}
			if err != nil {
				t.Fatal(err)
			}
			sentinel := filepath.Join(outside, "unrelated-data")
			if err := os.WriteFile(sentinel, []byte("preserve"), 0600); err != nil {
				t.Fatal(err)
			}
			if kind == "writable" {
				err = os.Chmod(directory, 0777)
