func TestConnectedEnrollmentDoesNotReadVaultOrRunUp(t *testing.T) {
	e := testEnroller(t)
	var commands []string
	e.run = func(ctx context.Context, binary string, args ...string) ([]byte, error) {
		commands = append(commands, args[0])
		if args[0] == "debug" {
			return []byte(appliedConfigJSON), nil
		}
