	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	defer listener.Close()
	go func() {
		for {
			conn, err := listener.Accept()
			if err != nil {
				return
			}
			conn.Close()
		}
	}()
	var calls int
	prober := &Prober{Now: time.Now, Regions: func(context.Context) ([]string, error) { return []string{"us-ashburn-1", "invalid/region"}, nil },
