				if err != nil {
					return nil, err
				}
				response, err := server.Client().Do(request)
				if err != nil {
					return nil, err
				}
				if response.StatusCode != http.StatusOK {
					_ = response.Body.Close()
					return nil, errors.New("retained evidence object is absent")
				}
