func TestHostMetricStreamOpenPreservesGenerationAndRejectsOldContract(t *testing.T) {
	first := hostMetricTestStream(t, hostMetricBroker(t, t.TempDir(), -1))
	second, err := OpenHostMetricStream(t.Context(), first.js, "gru", 1)
