	server, _ := newLoginServer(t)
	store := server.sessions.binding.Load().store
	value, err := server.sessions.issue(t.Context())
	if err != nil {
		t.Fatal(err)
	}
	before, err := store.kv.Status(t.Context())
	if err != nil {
		t.Fatal(err)
	}
