func TestReadNetDevSumsNonLoopbackInterfaces(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	cases := map[string]struct {
		content string
		rx, tx  uint64
		ok      bool
	}{
		"fixture":   {content: testNetDev, rx: 1500, tx: 2300, ok: true},
